import React, { InputHTMLAttributes }  from 'react'

import Button from '../../components/Button';
import Header from '../../components/Header';
import Input from '../../components/Input';
import InputImage from '../../components/InputImage';
import TextArea from '../../components/TextArea';
import { useNavigate } from 'react-router-dom';
import { RegisterWrapper, BodyRegisterContainer, InputRegisterContainer, ButtonWrapper, ButtonContainer, TextAreaContainer, ImageUpload,ImagePreview } from './styles';
import { useState, } from 'react';
import { Photo } from '../../types/photo';
import ImageUploading, { ImageListType } from "react-images-uploading";





const Register = () => {


    const [images, setImages] = React.useState([]);
    const maxNumber = 8;
  
    const onChange = (
      imageList: ImageListType,
      addUpdateIndex: number[] | undefined
    ) => {
      // data for submit
      console.log(imageList, addUpdateIndex);
      setImages(imageList as never[]);
    };

    

    const navigate = useNavigate();
    const handleToRegister = () => {
        navigate('/dashboard');
    }
    return (
        <RegisterWrapper>
            <Header/>
            <h1>Register your land</h1>
            <BodyRegisterContainer>

                <ImageUpload style={{marginBottom:"2rem"}} >
                <div className="App">
      <ImageUploading
        multiple
        value={images}
        onChange={onChange}
        maxNumber={maxNumber}
      >
        {({
          imageList,
          onImageUpload,
          onImageRemoveAll,
          onImageUpdate,
          onImageRemove,
          isDragging,
          dragProps
        }) => (
          // write your building UI
          <div className="upload__image-wrapper">
            <button
              style={isDragging ? { color: "red" } : undefined}
              onClick={onImageUpload}
              {...dragProps}
            >
              Click or Drop here
            </button>
            &nbsp;
            <button onClick={onImageRemoveAll}>Remove all images</button>
            {imageList.map((image, index) => (
              <div key={index} className="image-item">
                <img src={image.dataURL} alt="" width="100" />
                <div className="image-item__btn-wrapper">
                  <button onClick={() => onImageUpdate(index)}>Update</button>
                  <button onClick={() => onImageRemove(index)}>Remove</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </ImageUploading>
    </div>
                </ImageUpload>
               

                <InputRegisterContainer style={{marginTop:"70px"}}>
                    <Input placeholder='Title*' />
                </InputRegisterContainer>

                <TextAreaContainer>
                    <TextArea placeholder='Description*' />
                </TextAreaContainer>
                <InputRegisterContainer>
                    <Input placeholder='Beds*'/>
                </InputRegisterContainer>
                <InputRegisterContainer>
                    <Input placeholder='Baths*' />
                </InputRegisterContainer>
                <InputRegisterContainer>
                    <Input placeholder='Yr Built?*' />
                </InputRegisterContainer>
                <InputRegisterContainer style={{width: "20%"}} >
                    <Input placeholder='value*' />
                </InputRegisterContainer>
                <InputRegisterContainer>
                    <Input placeholder='Sqft*' />
                </InputRegisterContainer>

                <InputRegisterContainer>
                    <Input placeholder='Address*' />
                </InputRegisterContainer>
              
                <InputRegisterContainer>
                    <Input placeholder='district*' />
                </InputRegisterContainer>

                <InputRegisterContainer>
                    <Input placeholder='City*' />
                </InputRegisterContainer>
                <InputRegisterContainer>
                    <Input placeholder='State*' />
                </InputRegisterContainer>
       
               
            </BodyRegisterContainer>
            <ButtonWrapper>
                <ButtonContainer>
                    <Button type='button' onClick={handleToRegister} style={{borderRadius:"30px"}}>Register</Button>
                </ButtonContainer>
            </ButtonWrapper>
        </RegisterWrapper>

    )
}

export default Register
